create table if not exists note (
    id bigint generated by default as identity primary key,
    uuid uuid not null unique,
    content text not null
);

-- Kept on purpose for comparison, not to be removed: the same table with table-level constraints.
-- It names the constraints as PostgreSQL names the inline ones, so both variants produce an identical table;
-- a change to the table above is made here as well.
-- create table if not exists note (
--     id bigint generated by default as identity,
--     uuid uuid not null,
--     content text not null,
--     constraint note_pkey primary key (id),
--     constraint note_uuid_key unique (uuid)
-- );
